import sys

def max_ones(n, m):
    if m == 1:
        return n * n
    if n < m:
        return 0
    return (n - m + 1) * (n - m + 1)

def find_n_m(x):
    if x == 0:
        return 1, 1
    for m in range(1, 1000001):
        for n in range(m, 1000001):
            if max_ones(n, m) == x:
                return n, m
    return -1, -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    x_values = list(map(int, data[1:1+t]))

    results = []
    for x in x_values:
        n, m = find_n_m(x)
        if n == -1:
            results.append(-1)
        else:
            results.append(f"{n} {m}")

    print("\n".join(results))

if __name__ == "__main__":
